252		This result is imported from Theorem~6.9 of~\cite{Coladangelo2017Robust}. There are two minor differences between their statement and the one given here. First, they state a robustness of $O(\eps)$, but measure the closeness of the actual and ideal states in trace norm; expressed as the Euclidean distance between $\phi_{\mathrm A} \ot \phi_{\mathrm B}\ket{\psi}$ and $\ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}}$, this becomes $O(\sqrt\eps)$. Second, their ideal observables for the $\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ questions are $I \ot \sigma^Z$ and $\sigma^Z\sigma^X \ot \sigma^Z\sigma^X$; under a local change of basis these are equivalent to $\sigma^X \ot I$ and $\sigma^Z \ot I$, respectively.
253	\end{proof}
254	
255	The converse construction shows that any pair of anticommuting binary observables yields a perfect strategy for the Magic Square game.
256	
257	\begin{theorem}\label{thm:ms-from-ac}
258		\lean{MIPStarRE.QPBT.obsOf, MIPStarRE.QPBT.exists_ms_perfect_strategy_of_anticommuting}
259		\leanok
260		\uses{def:ms-game, def:consistent-measurement, def:spcc, def:EPR, def:tensor-product-value}
261		Let $A = \{A_b\}_{b \in \F_2}$ and $B = \{B_b\}_{b \in \F_2}$ be two-outcome projective measurements acting on $(\C^q)^{\ot n}$ that are consistent on $\ket{\mathrm{EPR}_q}^{\ot n}$ (Definition~\ref{def:consistent-measurement}), and let $\mathcal O_A = A_0 - A_1$ and $\mathcal O_B = B_0 - B_1$ be the corresponding $\pm 1$-valued observables. Suppose that $\mathcal O_A \mathcal O_B = - \mathcal O_B \mathcal O_A$. Then there exists a symmetric strategy $\mathcal S = (\psi, M)$ for the Magic Square game with the following properties:
262		\begin{enumerate}
263			\item $\mathcal S$ is an SPCC (symmetric, projective, consistent, commuting) strategy of value $1$;
264			\item the state is $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot n} \ot \ket{\mathrm{EPR}_2}$;
265			\item for $b \in \{0,1\}$, $M^{\mathsf{Variable}_1}_b = A_b \ot I$ and $M^{\mathsf{Variable}_5}_b = B_b \ot I$.
266		\end{enumerate}
267	\end{theorem}
268	\begin{proof}
269		\uses{def:consistent-measurement}
270		The strategy is based on the canonical two-qubit operator solution of the Magic Square, with the state $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot n} \ot \ket{\mathrm{EPR}_2}$ and the cells of the grid assigned the $\pm 1$-valued observables

550	The question set $\type^\ms$ of the Magic Square game is the following:
551	\begin{equation*}
552	  \begin{split}
553	    \type^\msc & = \{ \Constraint_i : i = 1, 2, \ldots, 6\}\;,\\
554	    \type^\msv & = \{ \Variable_j : j = 1, 2, \ldots, 9\}\;,\\
555	    \type^\ms & = \type^\msc \cup \type^\msv\;.
556	  \end{split}
557	\end{equation*}
558	The questions $\Constraint_i$ for $i \in \{1,2,3\}$ correspond to the three row
559	constraints, the questions $\Constraint_4$, $\Constraint_5$ correspond to the first
560	two column constraints, and question $\Constraint_6$ corresponds to the third
561	column constraint.
562	
563	In the Magic Square game, the verifier first samples a constraint $\Constraint_i
564	\in \type^\msc$ uniformly at random, and then samples $\Variable_j$, one of the
565	three variables in the row or column corresponding to $\Constraint_i$, uniformly
566	at random.
567	One player is randomly assigned to be the $\Constraint$ player, and the other is
568	assigned to be the $\Variable$ player.
569	The $\Constraint$ player is sent the question $\Constraint_i$ and is expected to
570	respond with three bits $(\beta_{v_1}, \beta_{v_2}, \beta_{v_3}) \in \F_2^3$,
571	where $(v_1,v_2,v_3)$ are the indices of the three variables corresponding to
572	$\Constraint_i$.
573	The $\Variable$ player is given question $\Variable_j$ and is expected to
574	respond with a single bit $\gamma \in \F_2$.
575	The players win if the $\Constraint$ player's answers satisfy the equation
576	associated with $\Constraint_i$, and $\gamma = \beta_j$.
577	More precisely, the verifier samples an edge of the type graph (see Section~\ref{sec:types}) $G^\ms$
578	in Fig.~\ref{fig:type-graph-ms}, sends one endpoint to a random player, and the
579	other endpoint to the other player.
580	
581	\begin{figure}[!htbp]
582	  \centering
583	  \begin{tikzpicture}[scale=.8]
584	
585	    \tikzset{type/.style args={[#1]#2}{
586	        draw,circle,fill,scale=0.25,
587	        label={[font=\scriptsize, label distance=1pt]#1:#2}
588	      }}
589	
590	
591	
592	    \foreach \i in {1,...,6} \draw (0,8-9/8*\i)
593	    coordinate (Constraint-\i)
594	    node[type={[180]$\Constraint_\i$}] {};
595	
596	    \foreach \i in {1,...,9} \draw (2.5,9-\i)
597	    coordinate (Variable-\i)
598	    node[type={[0]$\Variable_\i$}] {};
599	
600	    \foreach \i in {1,...,3} \foreach \j in {1,...,3}
601	    \pgfmathsetmacro{\k}{(\i-1)*3+\j}
602	    \draw (Constraint-\i) -- (Variable-\k);
603	
604	    \foreach \i in {4,...,6} \foreach \j in {1,...,3}
